// Package httpapi implements the RESTful API generated by oapi-codegen.
//
// STEP 5 — Every HTTP handler translates the REST request into gRPC call(s),
// and the gRPC reply (or error) back into a REST response:
//
//	client --HTTP/JSON--> Handlers --gRPC--> Inventory server (this node or a peer)
//
// Eight REST operations share six RPCs:
//
//	GET    /v1/products, /v1/products/{sku}  -> ReadProducts   (server stream)
//	DELETE /v1/products, /v1/products/{sku}  -> DeleteProducts (client stream)
//	POST   /v1/products                      -> CreateProduct
//	PATCH  /v1/products/{sku}                -> UpdateProduct
//	PATCH  /v1/products/{sku}/stock          -> AddStock
//	POST   /v1/orders                        -> PlaceOrder     (client stream)
//
// Handlers hold NO application state. That is deliberate: in Parts II-III
// the gRPC target becomes "the server responsible for this request", which
// is exactly the forwarding required by the assignment.
package httpapi

import (
	"context"
	"encoding/json"
	"errors"
	"io"
	"net/http"
	"net/url"
	"strconv"
	"strings"

	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/metadata"
	"google.golang.org/grpc/status"

	inventoryv1 "github.com/your-team/inventory/gen/inventory/v1"
	"github.com/your-team/inventory/gen/rest"
)

// Handlers implements rest.StrictServerInterface (one method per operationId).
type Handlers struct {
	Inventory inventoryv1.InventoryClient
}

// Compile-time check: the build fails here if a method is missing or has the
// wrong signature after you change openapi.yaml and regenerate.
var _ rest.StrictServerInterface = (*Handlers)(nil)

// NewHTTPHandler wires the strict handlers into a net/http mux.
func NewHTTPHandler(inventory inventoryv1.InventoryClient, mux *http.ServeMux) http.Handler {
	strict := rest.NewStrictHandlerWithOptions(&Handlers{Inventory: inventory}, nil, rest.StrictHTTPServerOptions{
		// Malformed request bodies (bad JSON) -> 400.
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			writeProblem(w, http.StatusBadRequest, err.Error())
		},
		// Errors returned by the handlers below (usually gRPC errors).
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			writeProblem(w, httpStatusFromGRPC(err), errorMessage(err))
		},
	})
	return rest.HandlerWithOptions(strict, rest.StdHTTPServerOptions{
		BaseRouter: mux,
		// Bad parameters (e.g. limit=abc, no sku) -> 400, as problem+json too.
		ErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			writeProblem(w, http.StatusBadRequest, err.Error())
		},
	})
}

// ---------------------------------------------------------------------------
// Reads
// ---------------------------------------------------------------------------

// GET /v1/products?sku=..&sku=.. | ?prefix=..  [&inStock=&sort=&limit=&consistency=]
func (h *Handlers) ListProducts(ctx context.Context, req rest.ListProductsRequestObject) (rest.ListProductsResponseObject, error) {
	params := req.Params
	consistency, err := toProtoConsistency(params.Consistency)
	if err != nil {
		return nil, err
	}
	sortOrder, err := toProtoSort(params.Sort)
	if err != nil {
		return nil, err
	}
	if params.Sku != nil && params.Prefix != nil {
		return nil, status.Error(codes.InvalidArgument, "give at most one of sku or prefix")
	}
	readRequest := &inventoryv1.ReadProductsRequest{
		InStock:     deref(params.InStock),
		Sort:        sortOrder,
		Limit:       deref(params.Limit),
		Consistency: consistency,
	}
	if params.Sku != nil { // always a list, even for one sku: unknown ones are skipped, not 404
		readRequest.Select = &inventoryv1.ReadProductsRequest_SkuList{SkuList: &inventoryv1.SkuList{Skus: *params.Sku}}
	}
	if params.Prefix != nil {
		readRequest.Select = &inventoryv1.ReadProductsRequest_Prefix{Prefix: *params.Prefix}
	}

	stream, err := h.Inventory.ReadProducts(ctx, readRequest)
	if err != nil {
		return nil, err
	}
	products, err := recvProducts(stream)
	if err != nil {
		return nil, err // mapped to an HTTP status by ResponseErrorHandlerFunc
	}
	return rest.ListProducts200JSONResponse{Products: products}, nil
}

// GET /v1/products/{sku} — a ReadProducts of one product; its first message is it.
func (h *Handlers) GetProduct(ctx context.Context, req rest.GetProductRequestObject) (rest.GetProductResponseObject, error) {
	consistency, err := toProtoConsistency(req.Params.Consistency)
	if err != nil {
		return nil, err
	}
	stream, err := h.Inventory.ReadProducts(ctx, &inventoryv1.ReadProductsRequest{
		Select:      &inventoryv1.ReadProductsRequest_SingleSku{SingleSku: req.Sku},
		Consistency: consistency,
	})
	if err != nil {
		return nil, err
	}
	message, err := stream.Recv()
	if err != nil {
		return nil, err // NOT_FOUND -> 404
	}
	product := message.GetProduct()
	return rest.GetProduct200JSONResponse{
		Body:    productFromProto(product),
		Headers: rest.GetProduct200ResponseHeaders{ETag: ptr(etag(product.GetVersion()))}, // optional header -> *string
	}, nil
}

// ---------------------------------------------------------------------------
// Writes. Each one passes Client-Id and Request-Seq on to gRPC.
// ---------------------------------------------------------------------------

// POST /v1/products — 201 with the new product, its ETag and its Location.
func (h *Handlers) CreateProduct(ctx context.Context, req rest.CreateProductRequestObject) (rest.CreateProductResponseObject, error) {
	ctx = withRetryHeaders(ctx, req.Params.ClientId, req.Params.RequestSeq)
	newProduct := req.Body
	reply, err := h.Inventory.CreateProduct(ctx, &inventoryv1.CreateProductRequest{
		Sku:        newProduct.Sku,
		Name:       newProduct.Name,
		PriceCents: newProduct.PriceCents,
		Stock:      deref(newProduct.Stock),
	})
	if err != nil {
		return nil, err // ALREADY_EXISTS -> 409
	}
	product := reply.GetProduct()
	return rest.CreateProduct201JSONResponse{
		Body: productFromProto(product),
		Headers: rest.CreateProduct201ResponseHeaders{
			ETag:     ptr(etag(product.GetVersion())),
			Location: ptr("/v1/products/" + url.PathEscape(product.GetSku())),
		},
	}, nil
}

// PATCH /v1/products/{sku} — change the name and/or price.
func (h *Handlers) UpdateProduct(ctx context.Context, req rest.UpdateProductRequestObject) (rest.UpdateProductResponseObject, error) {
	expectedVersion, err := versionFromIfMatch(req.Params.IfMatch)
	if err != nil {
		return nil, err
	}
	ctx = withRetryHeaders(ctx, req.Params.ClientId, req.Params.RequestSeq)
	reply, err := h.Inventory.UpdateProduct(ctx, &inventoryv1.UpdateProductRequest{
		Sku:             req.Sku,
		Name:            req.Body.Name,
		PriceCents:      req.Body.PriceCents,
		ExpectedVersion: expectedVersion,
	})
	if err != nil {
		return nil, err // NOT_FOUND -> 404, ABORTED -> 412
	}
	product := reply.GetProduct()
	return rest.UpdateProduct200JSONResponse{
		Body:    productFromProto(product),
		Headers: rest.UpdateProduct200ResponseHeaders{ETag: ptr(etag(product.GetVersion()))},
	}, nil
}

// DELETE /v1/products/{sku} — a DeleteProducts stream with one product.
func (h *Handlers) DeleteProduct(ctx context.Context, req rest.DeleteProductRequestObject) (rest.DeleteProductResponseObject, error) {
	expectedVersion, err := versionFromIfMatch(req.Params.IfMatch)
	if err != nil {
		return nil, err
	}
	ctx = withRetryHeaders(ctx, req.Params.ClientId, req.Params.RequestSeq)
	err = h.sendDeletes(ctx, []*inventoryv1.DeleteProductsRequest{{Sku: req.Sku, ExpectedVersion: expectedVersion}})
	if err != nil {
		return nil, err // NOT_FOUND -> 404, ABORTED -> 412
	}
	return rest.DeleteProduct204Response{}, nil
}

// DELETE /v1/products?sku=..&sku=.. — all of them or none.
func (h *Handlers) DeleteManyProducts(ctx context.Context, req rest.DeleteManyProductsRequestObject) (rest.DeleteManyProductsResponseObject, error) {
	ctx = withRetryHeaders(ctx, req.Params.ClientId, req.Params.RequestSeq)
	var deletes []*inventoryv1.DeleteProductsRequest
	for _, sku := range req.Params.Sku {
		deletes = append(deletes, &inventoryv1.DeleteProductsRequest{Sku: sku})
	}
	err := h.sendDeletes(ctx, deletes)
	if err != nil {
		return nil, err // NOT_FOUND -> 404
	}
	return rest.DeleteManyProducts204Response{}, nil
}

// PATCH /v1/products/{sku}/stock — add units to the stock.
func (h *Handlers) AddStock(ctx context.Context, req rest.AddStockRequestObject) (rest.AddStockResponseObject, error) {
	ctx = withRetryHeaders(ctx, req.Params.ClientId, req.Params.RequestSeq)
	reply, err := h.Inventory.AddStock(ctx, &inventoryv1.AddStockRequest{Sku: req.Sku, Add: req.Body.Add})
	if err != nil {
		return nil, err // NOT_FOUND -> 404
	}
	product := reply.GetProduct()
	return rest.AddStock200JSONResponse{
		Body:    productFromProto(product),
		Headers: rest.AddStock200ResponseHeaders{ETag: ptr(etag(product.GetVersion()))},
	}, nil
}

// POST /v1/orders — a PlaceOrder stream, one message per order item.
func (h *Handlers) PlaceOrder(ctx context.Context, req rest.PlaceOrderRequestObject) (rest.PlaceOrderResponseObject, error) {
	ctx = withRetryHeaders(ctx, req.Params.ClientId, req.Params.RequestSeq)
	var orderItems []*inventoryv1.PlaceOrderRequest
	for _, orderItem := range req.Body.Items {
		orderItems = append(orderItems, &inventoryv1.PlaceOrderRequest{Sku: orderItem.Sku, Quantity: orderItem.Quantity})
	}
	reply, err := h.sendOrderItems(ctx, orderItems)
	if err != nil {
		return nil, err // NOT_FOUND -> 404, FAILED_PRECONDITION (not enough stock) -> 409
	}
	return rest.PlaceOrder200JSONResponse{
		Products:   productsFromProto(reply.GetProducts()),
		TotalCents: reply.GetTotalCents(),
	}, nil
}

// ---------------------------------------------------------------------------
// Streams: how a handler drives the three streaming RPCs
// ---------------------------------------------------------------------------

// recvProducts reads a ReadProducts stream to the end.
func recvProducts(stream inventoryv1.Inventory_ReadProductsClient) ([]rest.Product, error) {
	products := []rest.Product{} // serialize as [] rather than null
	for {
		message, err := stream.Recv()
		if errors.Is(err, io.EOF) { // the server finished sending
			return products, nil
		}
		if err != nil {
			return nil, err
		}
		products = append(products, productFromProto(message.GetProduct()))
	}
}

// sendDeletes sends every request on one DeleteProducts stream, then
// closes it; the server deletes all of them or none, and answers once.
func (h *Handlers) sendDeletes(ctx context.Context, deletes []*inventoryv1.DeleteProductsRequest) error {
	stream, err := h.Inventory.DeleteProducts(ctx)
	if err != nil {
		return err
	}
	for _, toDelete := range deletes {
		err = stream.Send(toDelete)
		if err != nil {
			break // the server ended the call early; CloseAndRecv returns why
		}
	}
	_, err = stream.CloseAndRecv()
	return err
}

// sendOrderItems works like sendDeletes, on a PlaceOrder stream.
func (h *Handlers) sendOrderItems(ctx context.Context, orderItems []*inventoryv1.PlaceOrderRequest) (*inventoryv1.PlaceOrderResponse, error) {
	stream, err := h.Inventory.PlaceOrder(ctx)
	if err != nil {
		return nil, err
	}
	for _, orderItem := range orderItems {
		err = stream.Send(orderItem)
		if err != nil {
			break
		}
	}
	return stream.CloseAndRecv()
}

// ---------------------------------------------------------------------------
// Helpers: REST <-> protobuf conversions and error mapping
// ---------------------------------------------------------------------------

// withRetryHeaders passes Client-Id and Request-Seq on to gRPC as metadata.
// Generic for the same reason as toProtoConsistency below.
func withRetryHeaders[ID ~string, Seq ~int64](ctx context.Context, clientID *ID, requestSeq *Seq) context.Context {
	if clientID != nil {
		ctx = metadata.AppendToOutgoingContext(ctx, "client-id", string(*clientID))
	}
	if requestSeq != nil {
		ctx = metadata.AppendToOutgoingContext(ctx, "request-seq", strconv.FormatInt(int64(*requestSeq), 10))
	}
	return ctx
}

// Generic so it works whether the generator types the parameter as
// rest.Consistency or as a type derived from it. Unknown values are a 400,
// never a silently weaker read.
func toProtoConsistency[T ~string](consistency *T) (inventoryv1.Consistency, error) {
	if consistency == nil {
		return inventoryv1.Consistency_CONSISTENCY_SEQUENTIAL, nil // the documented default
	}
	switch string(*consistency) {
	case "sequential":
		return inventoryv1.Consistency_CONSISTENCY_SEQUENTIAL, nil
	case "linearizable":
		return inventoryv1.Consistency_CONSISTENCY_LINEARIZABLE, nil
	default:
		return inventoryv1.Consistency_CONSISTENCY_UNSPECIFIED,
			status.Errorf(codes.InvalidArgument, "unknown consistency %q", string(*consistency))
	}
}

// toProtoSort turns "stock" / "-stock" into a SortOrder; unknown values are a 400.
func toProtoSort[T ~string](sortParam *T) (*inventoryv1.SortOrder, error) {
	if sortParam == nil {
		return nil, nil // default: by sku, ascending
	}
	fieldName, descending := strings.CutPrefix(string(*sortParam), "-")
	sortOrder := &inventoryv1.SortOrder{Descending: descending}
	switch fieldName {
	case "sku":
		sortOrder.Field = inventoryv1.SortOrder_FIELD_SKU
	case "name":
		sortOrder.Field = inventoryv1.SortOrder_FIELD_NAME
	case "priceCents":
		sortOrder.Field = inventoryv1.SortOrder_FIELD_PRICE_CENTS
	case "stock":
		sortOrder.Field = inventoryv1.SortOrder_FIELD_STOCK
	default:
		return nil, status.Errorf(codes.InvalidArgument, "unknown sort %q", string(*sortParam))
	}
	return sortOrder, nil
}

func productFromProto(product *inventoryv1.Product) rest.Product {
	return rest.Product{
		Sku:        product.GetSku(),
		Name:       product.GetName(),
		PriceCents: product.GetPriceCents(),
		Stock:      product.GetStock(),
		Version:    product.GetVersion(),
	}
}

func productsFromProto(products []*inventoryv1.Product) []rest.Product {
	converted := make([]rest.Product, 0, len(products))
	for _, product := range products {
		converted = append(converted, productFromProto(product))
	}
	return converted
}

// An ETag is the version in quotes, e.g. "3".
func etag(version int64) string { return strconv.Quote(strconv.FormatInt(version, 10)) }

// versionFromIfMatch parses an If-Match header; nil means "no condition".
// Only one quoted version like "3" is accepted; anything else is a 400.
func versionFromIfMatch(ifMatch *string) (*int64, error) {
	if ifMatch == nil || *ifMatch == "" {
		return nil, nil
	}
	versionText, opened := strings.CutPrefix(*ifMatch, `"`)
	versionText, closed := strings.CutSuffix(versionText, `"`)
	version, err := strconv.ParseUint(versionText, 10, 63) // digits only: no sign, no W/
	if !opened || !closed || err != nil {
		return nil, status.Errorf(codes.InvalidArgument, "If-Match %q is not a version", *ifMatch)
	}
	expectedVersion := int64(version)
	return &expectedVersion, nil
}

func ptr[T any](value T) *T { return &value }

func deref[T any](pointer *T) T {
	var zero T
	if pointer == nil {
		return zero
	}
	return *pointer
}

// httpStatusFromGRPC is the single place where gRPC status codes become HTTP
// status codes. Keep it consistent with the responses in openapi.yaml.
func httpStatusFromGRPC(err error) int {
	_, isGRPCStatus := status.FromError(err)
	if !isGRPCStatus {
		if errors.Is(err, context.DeadlineExceeded) {
			return http.StatusGatewayTimeout
		}
		return http.StatusInternalServerError
	}
	switch status.Code(err) {
	case codes.NotFound:
		return http.StatusNotFound // 404
	case codes.InvalidArgument:
		return http.StatusBadRequest // 400
	case codes.AlreadyExists:
		return http.StatusConflict // 409: the sku already exists
	case codes.FailedPrecondition:
		return http.StatusConflict // 409: not enough stock, or an old Request-Seq
	case codes.Aborted:
		return http.StatusPreconditionFailed // 412: If-Match differs from the version
	case codes.Unimplemented:
		return http.StatusNotImplemented // 501
	case codes.Unavailable:
		return http.StatusServiceUnavailable // 503: e.g. the other node is down
	case codes.DeadlineExceeded:
		return http.StatusGatewayTimeout // 504
	default:
		return http.StatusInternalServerError // 500
	}
}

func errorMessage(err error) string {
	grpcStatus, isGRPCStatus := status.FromError(err)
	if isGRPCStatus {
		return grpcStatus.Message()
	}
	return err.Error()
}

// writeProblem writes an RFC 9457 problem-details body.
func writeProblem(w http.ResponseWriter, code int, detail string) {
	w.Header().Set("Content-Type", "application/problem+json")
	w.WriteHeader(code)
	_ = json.NewEncoder(w).Encode(rest.Problem{
		Title:  http.StatusText(code),
		Status: code,
		Detail: &detail,
	})
}
